fn is_end(&self, version, _rnd, player, data, team_plan, _debug) -> bool

// L164  team_plan.take_active(JungleType::Morgard) == false 면 즉시 종료
//       (take_active(team_plan.rs:243) -> objective_target(team_plan.rs:230~231) 가 인라인 + 상수접힘되어
//        IR 에는 `team_plan.objective 태그(+0x41f) == 0(Morgard)` 비교만 남음)
if team_plan.objective 태그 != 0 /*Morgard 아님(None=255 포함)*/ { return true }

// L169
let camp_pos: (u64,u64) = data.context.map.camp_pos(JungleType::Morgard, player.info.team == 0);

// L172  take_setup_like(team_plan.rs:257~258) 인라인
let setup_like = (team_plan.objective 태그 == 0/*Morgard*/) && (team_plan.objective.phase(+0x420) == 1/*Setup*/);

// L173
if setup_like {
    // L174
    if TeamPlan::v24_objective_setup_should_release_to_passive(team_plan, version, player, data, JungleType::Morgard) {
        return true;
    }
    // L179  아군 팀 시야로 에픽 캠프 셀이 보이는가 (vtable+0x100)
    if data.cache.game.<vt+0x100>(player.info.team, camp_pos.0/32000, camp_pos.1/32000) {
        // L180~181  적팀 챔피언 5칸을 훑어 '최근에 본' 적 중 캠프에 가장 가까운 하나
        //   iter_champions(1 - player.info.team) = AbstractGameWithCache.player_champion[1-team] ([Option<&Entity>;5])
        //   filter 술어(closure$0, 담당 범위 밖에 인라인) =
        //       data.blackboard[1 - player.info.team].is_recent_visible(data.cache.game, player, e)
        //   min_by_key 키 = distance_sq(e.x, e.y, camp_pos.0, camp_pos.1)
        let nearest_to_camp_enemy = ...min_by_key(...);
        // L183
        if let Some(n) = nearest_to_camp_enemy {
            // L184  abs_diff 로 dx,dy 를 만들어 dx*dx+dy*dy
            if distance_sq(n.x, n.y, camp_pos.0, camp_pos.1) > 22500000000 /*150000^2*/ { return true; }
        } else {
            return true;   // 조건에 맞는 적 챔피언이 하나도 없으면 종료
        }
    }
}

// L193  에픽 몬스터 엔티티가 현재 살아 있는가
let moba = data.cache.game.<vt+0x40 mode>().as_moba().unwrap();   // GameMode 태그 0 == Moba, 아니면 unwrap_failed 패닉
let epic = moba.jungle_runner.epic.live_list.get(0)              // len(+0x1a8)==0 이면 None
              .and_then(|e| data.cache.game.<vt+0x1f0 entity>(*e));   // closure$2

// L194  살아 있으면 종료 아님. 죽어 있으면 '리스폰까지 15초 초과' 일 때만 종료
if epic.is_some() { return false }
let moba = data.cache.game.<vt+0x40 mode>().as_moba().unwrap();   // 소스가 다시 한 번 호출(IR 에 두 번 나타남)
return moba.jungle_runner.epic.next_respawn_tick.saturating_sub(data.cache.game.<vt+0x28 tick>())
       > data.context.setting.tick_per_second * 15;

// 반환 경로 요약(IR phi 기준)
//   true  : L164 목표가 Morgard 아님 / L174 규율계층이 패시브 해제 지시 / L183 적 없음 / L184 최근접 적이 150000 초과
//   false : L194 에픽이 살아 있음
//   식값  : L194 리스폰 잔여틱 > tps*15
